// input too short or an output empty or too short.
func (c *Core) CDLIDENTICAL3CROWS(startIdx, endIdx int, inOpen, inHigh, inLow, inClose []float64, outInteger []int32) (OutRange, error) {
	if startIdx < 0 || startIdx > IndexMax {
		return OutRange{}, OutOfRangeStartIndex
	}
	if endIdx < 0 || endIdx > IndexMax || endIdx < startIdx {
		return OutRange{}, OutOfRangeEndIndex
	}
	lookback := int(c.cdlidentical3crowsLookback())
	if lookback < 0 {
		return OutRange{}, BadParam
	}
	if len(inOpen) < endIdx+1 {
		return OutRange{}, BadParam
	}
	if len(inHigh) < endIdx+1 {
		return OutRange{}, BadParam
	}
	if len(inLow) < endIdx+1 {
		return OutRange{}, BadParam
	}
	if len(inClose) < endIdx+1 {
		return OutRange{}, BadParam
	}
	outLen := requiredOut(startIdx, endIdx, lookback)
	if len(outInteger) == 0 || len(outInteger) < outLen {
		return OutRange{}, BadParam
	}
	var outBegIdx, outNBElement int32
	if retCode := c.cdlidentical3crowsImpl(int32(startIdx), int32(endIdx), inOpen, inHigh, inLow, inClose, &outBegIdx, &outNBElement, outInteger); retCode != Success {
		return OutRange{}, retCode
	}
	return OutRange{BegIdx: int(outBegIdx), NBElement: int(outNBElement)}, nil
}

// CDLIDENTICAL3CROWSStream is a live CDLIDENTICAL3CROWS over a growing series:
// [CDLIDENTICAL3CROWSStream.Update] takes each new closed bar and returns the
// value [Core.CDLIDENTICAL3CROWS] computes at that bar over the same series.
// Open one with [Core.CDLIDENTICAL3CROWSOpen] or
// [Core.CDLIDENTICAL3CROWSOpenAndFill].
//
// A stream belongs to one goroutine; [CDLIDENTICAL3CROWSStream.Clone] forks it.
type CDLIDENTICAL3CROWSStream struct {
	core                                    *Core
	ShadowVeryShortPeriodTotal              [3]float64
	EqualPeriodTotal                        [3]float64
	ShadowVeryShortPeriodTotalRange1        float64
	ShadowVeryShortPeriodTotalTrailRange1   float64
	ShadowVeryShortPeriodTotalRange2        float64
	ShadowVeryShortPeriodTotalTrailRange2   float64
	EqualPeriodTotalRange2                  float64
	EqualPeriodTotalTrailRange2             float64
	lag1_inOpen                             float64
	lag2_inOpen                             float64
	lag1_inHigh                             float64
	lag2_inHigh                             float64
	lag1_inLow                              float64
	lag2_inLow                              float64
	lag1_inClose                            float64
	lag2_inClose                            float64
	ringPos_EqualTrailingIdx                int32
	ringCap_EqualTrailingIdx                int32
	ringLag_EqualTrailingIdx                int32
	ring_EqualTrailingIdx_derived           []float64
	ringPos_ShadowVeryShortTrailingIdx      int32
	ringCap_ShadowVeryShortTrailingIdx      int32
	ring_ShadowVeryShortTrailingIdx_derived []float64
	cs_Equal_rangeType                      int32
	cs_Equal_avgPeriod                      int32
	cs_Equal_factor                         float64
	cs_ShadowVeryShort_rangeType            int32
	cs_ShadowVeryShort_avgPeriod            int32
	cs_ShadowVeryShort_factor               float64
	cur_outInteger                          int32
	outRangeBegIdx                          int
	outRangeCount                           int
}

// OutRange returns the bars the stream has a value for, as
// [Core.CDLIDENTICAL3CROWS] reports them over the same bars; each Update and
// each Advance adds one to NBElement.
func (sp *CDLIDENTICAL3CROWSStream) OutRange() OutRange {
	return OutRange{BegIdx: sp.outRangeBegIdx, NBElement: sp.outRangeCount}
}

// Advance counts one bar the stream was not fed: OutRange grows by one and
// Value keeps its previous answer. It returns [OutOfRangeEndIndex] once
// OutRange reaches bar [IndexMax].
func (sp *CDLIDENTICAL3CROWSStream) Advance() error {
	if sp.outRangeBegIdx+sp.outRangeCount > IndexMax {
		return OutOfRangeEndIndex
	}
	sp.outRangeCount++
	return nil
}

// Update commits one closed bar (inOpen, inHigh, inLow and inClose) and returns
// the new value. It returns [BadParam] for a bar value that is not finite and
// [OutOfRangeEndIndex] once OutRange reaches bar [IndexMax], both before
// anything changes.
func (sp *CDLIDENTICAL3CROWSStream) Update(inOpen, inHigh, inLow, inClose float64) (int32, error) {
	if sp.outRangeBegIdx+sp.outRangeCount > IndexMax {
		return 0, OutOfRangeEndIndex
	}
	if !isFinite(inOpen) || !isFinite(inHigh) || !isFinite(inLow) || !isFinite(inClose) {
		return 0, BadParam
	}
	cdlidentical3crowsStepImpl(sp, inOpen, inHigh, inLow, inClose)
	sp.outRangeCount++
	return sp.cur_outInteger, nil
}

